import geoJson from "../data/territories.geo.json";

const geo = geoJson as unknown as Record<string, unknown>;

/** [minX, minY, width, height] of the map space. */
export const VIEWBOX = geo._viewBox as [number, number, number, number];
/** Territory id -> SVG path data (generated by scripts/generate-territories.mjs). */
export const TERRITORY_PATHS: Record<string, string> = Object.fromEntries(
  Object.entries(geo).filter(([k, v]) => !k.startsWith("_") && typeof v === "string") as [string, string][],
);
/** Region id -> outline path (mainland plus islands). */
export const REGION_PATHS = geo._regions as Record<string, string>;
/** Island and cross-sea links drawn as dashed lines. */
export const SEA_LINKS = geo._seaLinks as [string, string][];
export const LAKES = geo._lakes as string[];
export const RIVERS = geo._rivers as { name: string | null; size: number; d: string }[];
export const ROADS = geo._roads as { name: string | null; size: number; d: string }[];
export const MOUNTAINS = geo._mountains as [number, number][];
/** Land that belongs to no territory (Skagos): drawn, not selectable. */
export const SCENERY = geo._scenery as string;
/** Names for scenery regions (the Vale). */
export const SCENERY_LABELS = geo._sceneryLabels as { name: string; pos: [number, number]; size: number }[];
export const WALL_LINE = geo._wall as string;
